    ["使用后获得花式待机动作:<Highlight>掌中笼</>"] = "После использования вы получите особую анимацию ожидания: <Highlight>Клетка в ладони</>",
    ["使用后获得花式待机动作:<Highlight>整理头发</>"] = "Используйте, чтобы получить особую анимацию бездействия: <Highlight>Поправить волосы</>",
    ["使用后获得花式待机动作:<Highlight>查看时间</>"] = "Используйте для получения необычного действия в режиме ожидания: <Highlight> Время проверки </>",
    ["使用后获得花式待机动作:<Highlight>森影金蝶</>"] = "Используйте, чтобы получить Fancy Idle Action: <Highlight> Лесная тень, Золотая бабочка </>.",
    ["使用后获得花式待机动作:<Highlight>王朝拂光</>"] = "После использования вы получите особую анимацию ожидания: <Highlight>Отблеск династии</>",
    ["使用后获得花式待机动作:<Highlight>登临王座</>"] = "После использования вы получите особую анимацию ожидания: <Highlight>Восхождение на трон</>",
    ["使用后获得花式待机动作:<Highlight>祈愿之星</>"] = "После использования вы получите особую анимацию ожидания: <Highlight>Звезда желаний</>",
    ["使用后获得花式待机动作:<Highlight>自我欣赏</>"] = "Используйте, чтобы получить Необычное праздное действие: <Highlight> Самовосхваление </>.",
    ["使用后获得花式待机动作:<Highlight>花丛之憩</>"] = "Используйте, чтобы получить Необычное праздное действие: <Highlight> Отдых в цветах </>.",
    ["使用后获得花式待机动作:<Highlight>赞美愚者</>"] = "При использовании даёт особую анимацию ожидания: <Highlight>Восславь Шута</>",
    ["使用后获得花式待机动作:<Highlight>转枪</>"] = "После использования вы получите необычное действие в режиме ожидания: <Highlight>Поворотный пистолет</>.",
    ["使用后获得花式待机动作:<Highlight>轻摇杯盏</>"] = "После использования вы получите необычные действия в режиме ожидания: <Highlight> Аккуратно встряхните чашку </>",
    ["修行无穷无尽，星轨与塔罗永不停歇。持续向奥秘前进，占卜出更多关于未来的启迪。"] = "Совершенствование бесконечно, звездные тропы и Таро никогда не прекращаются. Продолжайте продвигаться к тайнам, предсказывая будущее.",
    ["修长利落的战场剪影，代表秩序的开端。"] = "Стройный и четкий силуэт на поле боя, олицетворяющий начало порядка.",
    ["像旧宅走廊铺了一冬的地砖，踩上无声，却藏着说不清的安稳与温存。"] = "Подобно напольной плитке, уложенной на зиму в коридоре старого дома, наступить на нее бесшумно, но она скрывает в себе неописуемую стабильность и тепло.",
    ["像猫咪一样灵动地招手，是捉弄还是邀请？"] = "Помахать рукой, как кошка, это поддразнивание или приглашение?",
    ["兜帽遮面的老者，姿态谦卑地抚着胸口。最好别在他面前说悄悄话。"] = "Старик с закрытым лицом, в скромной позе поглаживающий грудь. Лучше не шептаться при нем.",
    ["冥河之畔，死亡与永恒共舞。她身披霜色骨纱而来。"] = "У реки Вечной Тьмы смерть и вечность танцуют вместе. Она появляется, закутанная в вуаль из кости морозного цвета.",
    ["冥河之畔，死亡与永恒共舞，黑灰的王冠在死寂中为他加冕。"] = "На берегу Реки Вечной Тьмы смерть танцует в унисон с вечностью, а пепельно-черный венец венчает его в могильном безмолвии.",
    ["凋落的花瓣，但仍能嗅到清香。"] = "Лепестки засохли, но аромат все еще чувствуется.",
    ["凝视深渊的人，终在深渊中看见自身。与恶龙缠斗太久，龙鳞早已覆上身躯。"] = "Тот, кто смотрит в бездну, в конце концов видит себя внутри нее. Слишком долго сражаясь со злыми драконами, тело уже покрыла драконья чешуя.",
    ["刀叉轻触瓷盘，银质餐具在烛光下泛着冷光，长桌两侧的贵族们，不得不收敛起所有失礼的念头。"] = "Ножи и вилки слегка касались фарфоровых тарелок, серебряная посуда блестела в свете свечей, а дворянам по обе стороны длинного стола приходилось сдерживать все невежливые мысли.",
    ["创造一切的主，全知全能的神，我等在此，再度等待着您的光芒照耀大地。"] = "Творец всего сущего, всеведущий и всемогущий Господь, мы здесь и вновь ждём, когда Твой свет озарит землю.",
    ["别看只是一苏勒，而小小钱币能撬动大大的愿望。"] = "Не смотрите свысока на то, что это просто один суле; крошечная монета может исполнить большое желание.",
    ["勇敢无畏，正直英勇。"] = "Храбрый и бесстрашный, честный и храбрый.",
    ["午后的阳光倾洒进咖啡杯，惬意的心情和拉花一般缤纷。"] = "Послеполуденное солнце проникает в чашку кофе, а уютное настроение такое же красочное, как латте-арт.",
    ["华发如冷焰，似乎在讲述来自上个时代的传说。"] = "Седые волосы, подобные холодному пламени, будто бы повествуют о преданиях минувшей эпохи.",
    ["华彩在深黑之上流淌，诡谲却又优雅，令一切庸俗的颜色都黯然。"] = "Блеск струится поверх глубокого черного цвета, жуткий, но элегантный, затмевая все вульгарные цвета.",
    ["即使只是某个神秘封印物的仿品，也不要随便许愿哦？"] = "Даже если это всего лишь копия какого-то загадочного Запечатанного Артефакта, не загадывайте желания случайно, ладно?",
    ["即使身居果壳之中，仍然自以为无限空间之王。"] = "Несмотря на то, что он живет в ореховой скорлупе, он все еще думает, что он король бесконечного пространства.",
    ["即便在命运的巨变到来之际，也别忘记嘴角上扬，嘲弄于它。"] = "Даже когда наступят великие перемены судьбы, не забудь приподнять уголки рта и посмеяться над этим.",
    ["即便是误入的来客，也请遵从着装的礼仪。换上蓝白蕾丝的俏皮礼服，加入怪诞奇妙的茶会。"] = "Даже если вы случайно посетитель, пожалуйста, соблюдайте дресс-код. Наденьте игривое сине-белое кружевное платье и присоединяйтесь к причудливому и чудесному чаепитию.",
    ["即便是误入的来客，也请遵从着装的礼仪。换上蓝黑菱格的俏皮礼服，加入怪诞奇妙的茶会。"] = "Даже если вы случайно посетитель, пожалуйста, соблюдайте дресс-код. Наденьте игривое сине-черное клетчатое платье и присоединяйтесь к причудливому и чудесному чаепитию.",
    ["厚重的金边方框眼镜，让人联想起大学图书馆严肃而规矩的档案管理员。"] = "Массивные квадратные очки в золотой оправе напоминают о строгом и педантичном архивариусе из университетской библиотеки.",
    ["又是一声钟响，灰白和青黑交错的时钟表面，多了一根斑驳的时针。"] = "Вновь пробил колокол, и на серо-белом циферблате с сине-черными разводами прибавилась еще одна крапчатая часовая стрелка.",
    ["双臂交抱，进入旁观模式，并不急于参与其中。"] = "Скрещивает руки на груди, переходя в режим наблюдателя, не спеша вмешиваться.",
    ["发丝纷扬，犹如宣叙调演绎到至情之处，所有灯光为之聚焦。"] = "Волосы развеваются, как будто речитатив исполняется до самой эмоциональной точки, и на него направлен весь свет.",
    ["发尾飞旋，犹如咏叹调颂唱至剧情高潮，所有掌声为之倾倒。"] = "Кончики волос кружатся, словно ария, спетая к кульминации сюжета, на которую приходятся все аплодисменты.",
    ["古典雅致的客厅，看似空旷，实则处处透着精心布置的痕迹。"] = "Изысканная гостиная в классическом стиле: на первый взгляд просторная и пустая, но каждая деталь в ней выдает тщательную продуманность обстановки.",
    ["向月而生的成束繁花，汇聚成一个馨香的怀抱。"] = "Пучки цветов, растущие навстречу луне, сливаются в благоуханные объятия.",
    ["咏叹之白在裙裾间盛放，宣叙之金在大氅下翻涌，帷幕之下，他们谱写永不停歇的华章。"] = "Белизна арии цветет среди подолов юбок, золото речитатива струится под плащами; под занавесом они составляют главу, которая никогда не заканчивается.",
    ["唯有冰雪，亘古长存。万物在此凝止，时间至此失色。"] = "Только лед и снег будут длиться вечно. Здесь все останавливается, и время теряет свой цвет.",
    ["唯有被棋局认可之人，方成棋盘之上最终赢家。"] = "Лишь признанный шахматной партией станет последним победителем на доске.",
    ["喵喵喵~克喵亲手雕刻的南瓜灯闪亮登场！"] = "Мяу-мяу-мяу~ Тыквенный фонарь, вырезанный Клейном-мяу собственноручно, наконец-то сияет перед вами!",
    ["四皇齐聚，只有一人能够成为最后的赢家，一场足以改变世界局势的战争开始了。"] = "Четыре Императора собрались вместе, но лишь один сможет стать окончательным победителем — началась война, способная изменить расклад сил во всём мире.",
    ["圣光落处，即是破晓时分。神意所至，黎明将由此开启。"] = "Там, где падает Святой Свет, наступает рассвет. Там, где достигает божественная воля, начнётся утро.",
    ["圣洁的白色战马,身披大量白金重甲，金色光痕勾勒出神圣的烙印。"] = "Священный белый боевой конь, закованный в тяжелые платиновые доспехи, с золотыми светящимися следами, очерчивающими священное клеймо.",
    ["在一切尚未成形之前，世界是什么样子的？也许，就是这里。"] = "Каким был мир до того, как всё обрело форму? Возможно, таким, как здесь.",
    ["在世界面前垂首，为你献上虔诚的祈祷。"] = "Склонить голову перед миром и вознести за тебя истовую молитву.",
    ["在凝视深渊之时，深渊也在凝视你。或者，你可以选择成为深渊。"] = "Когда вы смотрите в бездну, бездна тоже смотрит на вас. Или вы можете стать бездной.",
    ["在城市的夜色中，人人都在为自己打算，红与黑沾染了野心，平庸才是罪恶。"] = "В ночи города каждый думает только о себе, красное и чёрное запятнаны амбициями, а заурядность — единственный грех.",
    ["在结伴而行的旅程与战斗中，不会再被菇毒所伤害。"] = "Во время совместных путешествий и сражений грибные токсины больше не причинят вам вреда.",
    ["在这片土地上，你是我最后的玫瑰。"] = "На этой земле ты моя последняя роза.",
    ["在非凡世界的深渊边缘，虔信是最后的缰绳。当所有确定的事物都在疯狂中溶解时，唯有信仰能将一个人锚定在人的边界之内。"] = "На краю бездны Мира Потусторонних набожность — последние поводья. Когда всё определенное растворяется в безумии, лишь вера может удержать человека в границах человеческого.",
    ["在黑暗中滑翔，用翅膀标记每一寸它飞过的领地。"] = "Скользит в темноте, используя крылья, чтобы отмечать каждый дюйм территории, над которой он пролетает.",
    ["墨色薄纱，遮敛秘影，却藏不住厄难蔷薇般的危险芬芳。"] = "Тюль чернильного цвета, скрывающий тайные тени, но неспособный скрыть опасный аромат, подобный розе бедствия.",
    ["大海之上疯狂的存在，皮手套下诞生千奇百怪的生命，每一株植物都是他的\"孩子\"，在实验中落地生根。"] = "Безумное существование над морем, странные жизни рождаются под кожаными перчатками. Каждое растение — его «дитя», укореняющееся в его экспериментах.",
    ["大阿卡纳中位居二十，审判牌。人无法在胸中豢养一条毒蛇，在灵魂的花园里日夜栽种荆棘。号角吹响，宽恕万物之时。"] = "Двадцатая карта Старших арканов — Суд. Человек не может растить в груди ядовитую змею и день и ночь сажать терновник в саду души. Звучит рог — время прощать всё сущее.",
    ["大阿卡纳中位居十七，星星牌。神圣的少女承托天穹的明星，愿温柔的星辰指引绝境逢生的方向。"] = "Семнадцатая карта Старших арканов — Звезда. Священная дева держит яркую звезду небосвода; пусть нежные звёзды укажут путь к спасению в безвыходном положении.",
    ["大阿卡纳中位居十三，死神牌。不知归处的亡灵骑士乘白马而来，它高举死亡的旗帜，终结一切新生。"] = "Тринадцатый среди Старших арканов — карта Смерти. Не знающий покоя рыцарь-мертвец является верхом на белом коне, высоко подняв знамя смерти, чтобы положить конец всему новому.",
    ["大阿卡纳中位居十五，恶魔牌。恶魔将利爪伸向祭品，蛊惑着人沉迷欲望的火焰，自甘堕落地坠向深渊。"] = "Пятнадцатый среди Старших арканов — карта Дьявола. Дьявол простирает острые когти к жертве, соблазняя человека утонуть в пламени желаний и добровольно пасть в бездну.",
    ["大阿卡纳中位居第七，战车牌。驱车持剑，直面所有磨难，坚定不移的意志是战士抵达应许之地的唯一支撑。"] = "Седьмая карта Старших арканов — Колесница. Мчаться на колеснице с мечом в руке, встречая лицом к лицу все невзгоды: непоколебимая воля — единственная опора Воина на пути в землю обетованную.",
    ["大阿卡纳中位居第四，皇帝牌。皇帝落座王位，身处权力之巅，统领世界的同时也深陷秩序的牢笼。"] = "Четвёртый среди Старших арканов — карта Императора. Император восседает на троне, на вершине власти, и, правя миром, сам оказывается пленником порядка.",
    ["天光柔和，让人恍惚觉得：也许事情还没那么糟。"] = "Мягкий дневной свет навевает обманчивое чувство: возможно, всё еще не так плохо.",
    ["夸张的肢体语言，戏剧性的情感表达。真相往往比戏剧更加荒诞。"] = "Преувеличенная жестикуляция, драматичное выражение эмоций. Правда зачастую нелепее любой драмы.",
    ["她已经离去，但银哨会一直唱着悠扬的歌，祝愿每一个心怀守护理想的人，美梦成真。"] = "Она ушла, но серебряный свисток всегда будет петь свою мелодичную песню, желая, чтобы каждый, кто мечтает о защите, увидел, как его мечты сбываются.",
    ["她甜美的笑容却像淬了蜜的刀，危险而美丽。"] = "Ее милая улыбка подобна ножу, смоченному медом, опасному и прекрасному.",
    ["如午夜星幕般深邃的紫色战马，少量银色战甲点缀，宛如夜色中的暗影。"] = "Боевой конь, темно-фиолетовый, как полуночный звездный занавес, украшенный небольшим количеством серебряных доспехов, похожий на тень в ночи.",
    ["如银月光华的战马，点缀白金战甲，金色光纹如流光溢彩于皮毛间游走。"] = "Боевой конь, подобный серебряному лунному свету, украшенный платиновой броней, с золотыми световыми узорами, струящимися по его шерсти, словно мерцающий свет.",
    ["如预言所说，在时间的尽头，一切命运都将收束于网中，所有传说都将燃烧至灰烬。"] = "Как гласит пророчество, в конце времён все судьбы сойдутся в одной сети, а все легенды сгорят дотла.",
    ["妈妈会化作蓝色的蝴蝶轻吻安西娅的发梢，从此，安西娅再也不怕被妈妈抛下了。"] = "Мама превратится в синюю бабочку и поцелует кончики волос Антеи. С этого момента Антея больше никогда не будет бояться, что мама ее бросит.",
    ["子爵夫人她就站在那里，等着苹果树开花，等着果实成熟，等着她一直在等的人。"] = "Виконтесса просто стояла и ждала, пока зацветет яблоня, ждала, пока созреют плоды, ждала человека, которого она всегда ждала.",
    ["学院的围墙上，青苔与泥土在方砖的缝隙里交替生长，一格青绿，一格棕黄。"] = "На стене академии в промежутках квадратных кирпичей попеременно растут мох и почва: одна сетка зеленая, одна сетка коричневато-желтая.",
    ["它伫立于失序的权能之上，嘲弄与颠覆一切既有的秩序。"] = "Он стоит над властью беспорядка, высмеивая и разрушая любой установленный порядок.",
    ["它将托起必然到来的启示，指引命运揭开下一张未知之牌。"] = "Он возвысит неизбежно грядущее откровение и направит судьбу открыть следующую неизвестную карту.",
    ["它把光收进怀里，等夜色邀约。"] = "Оно собирает свет в свои объятия, ожидая приглашения ночи.",
    ["安提哥努斯家族笔记的仿制品，但除了会吸引持有者写上“所有人都不会死，包括我”之外，没有别的非凡效果了。"] = "Копия Семейной записной книжки Антигона, но кроме надписи на держателе: «Все не умрут, включая меня», она не имеет других эффектов Потустороннего.",
    ["宫廷马场的大门再次敞开时，步伐与仪态，同样不曾松懈半分。"] = "Когда ворота королевского ипподрома снова открываются, темп и манера поведения остаются такими же острыми, как и прежде.",
    ["家族展台专属场景，家族等级2级时解锁使用。"] = "Эксклюзивная сцена для стендов «Семья», которую можно будет использовать, когда уровень семьи достигнет 2.",
    ["家族展台专属场景，家族等级6级时解锁使用。"] = "Особая сцена стенда семьи, открывается для использования на 6 уровне семьи.",
    ["将时间定格于翅膀轻轻扇动的刹那，此刻的蝴蝶仿佛正准备飞进谁的梦里。"] = "Время застыло в миг, когда крылья чуть вздрогнули; бабочка словно готовится влететь в чей-то сон.",
    ["层叠发旋，似乎传达着塔罗之中最深奥的秘密。"] = "Ниспадающие завитки волос словно приоткрывают глубочайшие тайны Таро.",
    ["左手和右手的快乐，通通都锁定你。"] = "Радость левой руки и правой руки — все нацелены на тебя.",
    ["年少的情愫天真纯洁，如春天，如甜美的春天，生机盎然。"] = "Юная привязанность невинна и чиста, как весна, как сладкий родник, полный жизненной силы.",
    ["并不会让非凡特性析出的高级仿制品。请放心佩戴。"] = "Высококачественные имитации, которые не вызовут характерных для Потусторонний осадков. Пожалуйста, носите с уверенностью.",
    ["并不是真正的太阳圣徽，也不是真正的变异太阳圣徽，请停止用其窥视永恒烈阳的尝试。"] = "Это не настоящая Священная Эмблема Солнца и не мутировавшая. Пожалуйста, прекратите использовать его, чтобы увидеть Вечное Сияющее Солнце.",
    ["并肩而战，是比铁更坚固的誓言。"] = "Сражаться плечом к плечу — клятва прочнее железа.",
    ["并非“秘偶熊”，而是秘偶“熊背包”。整个背包都是秘偶，所以不要乱丢哦！"] = "Не «мишка-марионетка», а марионетка «медвежий рюкзак». Весь рюкзак — марионетка, так что не разбрасывайте его!",
    ["幽绿星芒在塔顶无声流转，万物在此陷入永恒安眠，临近终结。"] = "Темно-зеленый звездный свет бесшумно струится на вершине башни; все вещи здесь погружаются в вечный сон, приближаясь к финишу.",
    ["序曲奏响，开场舞揭开盛宴的帷幕。第一缕晚风轻抚衣摆，夜色在轻柔吐息。"] = "Звучит увертюра, и танец открытия открывает пир. Первое дуновение вечернего ветерка касается поола платья, и ночь тихо дышит.",
    ["序章花瓣手臂"] = "Пролог Лепестковые руки",
    ["廷根机械坊走下的第一辆蒸汽座驾，是这座城市第一次听见机械代替马蹄的声音。它不快，也不华丽，但廷根所有驰骋街头的座驾，都是它的后辈"] = "Первый паровой автомобиль, выехавший из механической мастерской Тингена, стал первым случаем, когда город услышал звук машин, заменяющих лошадиные копыта. Он не быстрый и не броский, но каждое транспортное средство, скачущее по улицам Тингена, является его потомком.",
    ["当你看得越多，越会发现这个世界远比你想象的复杂。看似在打量别人，实则也是在确认自身的边界。"] = "Чем больше ты видишь, тем яснее понимаешь, что мир гораздо сложнее, чем тебе казалось. Кажется, что ты разглядываешь других, но на деле лишь определяешь собственные границы.",
    ["当我们的视线暂时从身为秩序阴影的结局转移，无尽的知识洪流也在罗塞尔的生命中谱写了抗争绝唱。"] = "Когда наш взгляд ненадолго отрывается от финала, ставшего тенью Порядка, бескрайний поток знаний также сложил в жизни Розеля последнюю песнь борьбы.",
    ["当迷雾散去时，旅人会发现脚下的路比想象中更柔软，原来绿野不只存在于传说里。"] = "Когда туман рассеется, путник обнаружит, что дорога под ногами мягче, чем представлялось; оказывается, зеленые поля существуют не только в легендах.",
    ["得到某位命运途径天使祝福的冰淇淋，拥有足够的美味和足够的幸运。"] = "Мороженое, благословлённое Ангелом Пути Судьбы, достаточно вкусное и приносит достаточно удачи.",
    ["微微拧身叉腰，让力与美的风采在此刻定格。"] = "Слегка поворачивая талию и руки на бедрах, позволяя стилю мощи и красоты застыть в этот момент.",
    ["心怀敬畏，窥探神秘，直至此身明晰万物之真理，方能止息。"] = "Сохраняйте трепет в своем сердце, проникайте в тайны, и только когда это тело поймет истину всего сущего, оно сможет обрести покой.",
    ["心理分析师偏爱的金边细框眼镜，用锐利的目光洞察一切隐藏。"] = "Очки в золотой оправе, любимые психологами, позволяют острым глазам проникнуть во все скрытое.",
    ["念诵诗句、剖析案情，跳脱与敏锐在同一个人身上交织，诗人同学身上藏着不为人知的故事。嘘……历史的主角，难免有其秘密。"] = "Читает стихи, разбирает дела — в одном человеке переплетаются отстранённость и проницательность. У нашего однокашника-поэта есть тайны, о которых никто не знает. Тсс... У героев истории неизбежно есть свои секреты.",
    ["思维钝化，意识漂浮。身体进入一种被“托管”的恍惚状态，顺从着外来的指引。"] = "Мышление притупляется, сознание словно плывёт. Тело впадает в транс, будто отданное под «опеку», подчиняясь чужим указаниям.",
    ["思考从来不是一件轻松的事情，每一次深入的思考与追问，都可能听见来自世界之外的回应。而清醒，是少数人还能保有的奢侈。"] = "Размышлять никогда не легко: каждое глубокое раздумье и вопрос могут вызвать отклик из-за пределов мира. А ясность рассудка — роскошь, доступная лишь немногим.",
    ["总之，带上它能感觉到知识涌入脑海。"] = "Короче говоря, его ношение заставляет вас чувствовать, как знания наполняют ваш разум.",
    ["您好！能占用一下您的时间吗！我想给您讲一讲我们的道标和救主！愚者先……愚者喵先生！"] = "Привет! Могу я занять минутку вашего времени? Я хочу рассказать вам о нашем маяке и спасителе! Шут... Мистер Мяу!",
    ["愿你和那位存在一样，在这座学识之都度过旅行开端最好的时光。"] = "Пусть и вам, подобно тому великому существу, доведётся провести самые прекрасные дни в начале вашего странствия по этой столице знаний.",
    ["或许你需要慢下来，坐在湖畔，静静感受着时光流逝，看着湖面倒映的天光云影。"] = "Возможно, вам нужно сбавить темп, посидеть у озера, тихо ощущая бег времени и глядя на отражение неба и облаков в воде.",
    ["手势递出邀请，眼神却悄悄点燃了试探的火星。"] = "Этот жест выражает приглашение, но глаза тихо зажигают искры испытания.",
    ["手腕轻轻转动，从容的姿态是你礼节性的铠甲。"] = "Легкое движение запястья: невозмутимая осанка служит вам броней благородного этикета.",
    ["把从容与力量戴在头上。"] = "Возложите на голову спокойствие и силу.",
    ["把欢乐与忠诚戴在头上。"] = "Увенчать голову радостью и верностью.",
    ["抬手致意，举止从容，就在此刻展现你的自信与完美。"] = "Поднимите руку в приветствии, держитесь непринуждённо — именно сейчас покажите свою уверенность и совершенство.",
    ["抵在头顶的指尖，将爱意轻灵地诉说。"] = "Кончики пальцев прижались к макушке, слегка говоря о любви.",
    ["拨弄时光的指针，遨游命运的影子，欺诈与恶作剧的化身——这些和鸦有什么关系呢？"] = "Перебирает стрелки времени, странствует в тени судьбы, воплощение обмана и проказ — какое отношение всё это имеет к ворону?",
    ["指尖轻轻一扬，便在人群里打捞出一个老熟人。"] = "Нежное движение кончиков пальцев, и из толпы вылавливается старый знакомый.",
    ["指尖轻轻一点，还原最不加粉饰的面颊。"] = "Нежное прикосновение кончиков пальцев восстанавливает самую некрасивую щеку.",
    ["挺直的脊背，让自信的你更值得信赖。"] = "Прямая спина делает уверенного в себе человека более заслуживающим доверия.",
    ["据说是小圆框眼镜的进阶产物，佩戴后专注力更上一层楼。"] = "Говорят, что это усовершенствованная версия маленьких круглых очков, их ношение еще больше улучшает концентрацию.",
    ["掠过夜空的兽影拥抱金属的冰冷，让面孔的温度隐于甲胄之后。你的心中是否也潜藏有野兽的嗥叫？"] = "Звериная тень, скользящая по ночному небу, обнимает холод металла, пряча тепло лица за доспехами. А не таится ли и в твоём сердце звериный вой?",
    ["摇柄转动，昔日的旋律便从中缓缓流淌而出。"] = "Рукоять поворачивается, и мелодия былых дней медленно струится из неё.",
    ["放缓脚步悠然前行，姿态自然随性，仿佛只是恰好从镜头前经过。  "] = "Замедлите шаг и идите неспешно, держась естественно и непринуждённо, будто просто случайно проходите мимо камеры.  ",
    ["敬畏命运，占卜悲欢。"] = "Почитай судьбу, гадание на радости и печали.",
    ["数年来，管家手中蓝色的银质摇铃都在忠诚地履行职责，将清脆铃声送抵庄园每一个角落。"] = "В течение многих лет синий серебряный колокольчик в руке дворецкого добросовестно выполнял свой долг, донося свой звонкий звон в каждый уголок поместья.",
    ["斩断狂信之线后，庞大的罪恶轰然落地。"] = "После того как нить фанатизма была перерезана, огромный грех с грохотом рухнул на землю.",
    ["旗过之处，皆为神选之阵。"] = "Где проходит знамя, там возникает строй, избранный богом.",
    ["无论在地下酒馆，还是南大陆的码头，赏金猎手都会获得人们充分的尊敬。毕竟谁也不想成为猎物，不是吗？"] = "Будь то в подземной таверне или в доках Южного континента, к охотникам за головами всегда относятся с полным уважением. Ведь никто не хочет стать добычей, верно?",
    ["无论是战场上的独行侠，还是做世界中的探索者，努力的勇者都值得嘉奖。"] = "Будь вы одиночкой на поле боя или исследователем мира, усердные храбрецы заслуживают награды.",
    ["无论窗外的世界多么晦暗，它们始终朝着光的方向。赞美太阳！"] = "Как бы ни была темна жизнь за окном, они всегда тянутся к свету. Славьте Солнце!",
    ["旧日都市废墟之上，浓重雾气掩盖之后，映出的是一轮金黄，那是遥不可及的故乡。"] = "Над руинами города Древних, за плотной пеленой тумана, отражается золотой диск. Это недосягаемая родина.",
    ["时代的主角，成长的传奇，也可以是你和我。"] = "Главным героем эпохи, легендой роста, также можем быть мы с вами.",
    ["明显不悦，耐心值可见地滑向低谷。"] = "Явно недовольный, уровень терпения заметно падает вниз.",
    ["星盘的辉光在步履下徐徐展开，无人知晓你的前路通往何处，但星辰永远在细数你的步伐。"] = "Сияние астролябии медленно расстилается под твоими шагами; никто не знает, куда ведет твоя дорога, но звезды вечно ведут счет твоим шагам.",
    ["星空为被，大地为床，篝火旁藏着冒险的梦想。"] = "Звездное небо как одеяло, земля как постель; мечты о приключениях прячутся у костра.",
    ["星空浩瀚，凡门皆达。愿旅途的星辉指引你们永不迷失。"] = "Звездное небо огромно, и все двери ведут к нему. Пусть звездный свет вашего путешествия направляет вас, чтобы вы никогда не заблудились.",
    ["星空浩瀚，凡门皆达。披戴此身，愿旅途的星辉指引你们永不迷失。"] = "Звездное небо огромно, и все двери ведут к нему. Нося это тело, пусть звездный свет путешествия поможет вам никогда не заблудиться.",
    ["星辰的轨迹，塔罗的秘义，彼此交错，占卜出关于未来的启迪。"] = "Траектории звезд и тайны Таро переплетаются, предсказывая просветление будущего.",
    ["显然，事情的发展超出了预期。"] = "Видно, что развитие событий превзошло ожидания.",
    ["晚风之中，步伐因舒适的衣衫而更加轻盈。明日也将是美好的明日。"] = "Вечерний ветерок делает шаги легче благодаря удобной одежде. Завтра тоже будет прекрасное завтра.",
    ["晨曦在脚下升起，照亮光辉之境。"] = "Заря поднимается под нашими ногами, освещая царство блеска.",
    ["晨祷者的衣角沾着露水和光线，每一步踏在颂歌的尾音上，将圣殿的宁静吟诵成行走的诗篇。"] = "Подол утреннего молящегося окрашен росой и светом; каждый шаг приходится на конец гимна, превращая спокойствие святилища в ходячую поэму.",
    ["普通的战马，身披简朴的少量战甲，是每个行者的忠实伙伴。"] = "Обычный боевой конь, одетый в простую минимальную броню, — верный спутник каждого путешественника.",
    ["晴天一样的好心情。"] = "Прекрасное настроение, словно ясный день.",
    ["暗紫色如深夜的战马，身披厚重银色战甲，如幽冥使者在人间巡游。"] = "Темно-фиолетовый, как полуночный боевой конь, одетый в тяжелые серебряные доспехи, бродящий по миру, как посланник из подземного мира.",
    ["暮霭吻过发丝，慵懒而缱绻。"] = "Твайлайт целует волосы, лениво и протяжно.",
    ["月色下踏潮而来，海天如潮汐晕染，袖口卷起千层雪浪，浪花永不停歇。"] = "Под луной он пришёл по приливу, море и небо расцветились, словно волны прилива, а на закатанных рукавах вздымаются тысячи слоёв снежных волн, и брызги не стихают никогда.",
    ["月色下踏潮而来，海天如潮汐晕染，长裙摆溅起月光碎沫，浪花永不停歇。"] = "Под луной она пришла по приливу, море и небо расцветились, словно волны прилива, а подол длинного платья взметает лунные брызги, и пена не стихает никогда.",
    ["未知的伟力翻涌于身躯之中，而抗争的烈焰永不熄灭。"] = "Неизвестная великая сила вспыхивает внутри тела, и пламя сопротивления никогда не угасает.",
    ["朴素但实用的新人衣装。"] = "Простой, но практичный наряд для новичков.",
    ["权欲汇于时代激流，野心点燃社会暗面。行于欲望与黑暗之间，你是追猎腐朽的捕手，也是搅弄风云的利剑。"] = "Жажда власти бурлит в потоке эпохи, а амбиции зажигают тёмную изнанку общества. Ступая меж желаниями и тьмой, ты и охотник, выслеживающий тлен, и разящий клинок, вершащий судьбы.",
    ["束起纷扰，专注此刻。"] = "Устраните хаос, сосредоточьтесь на настоящем.",
    ["来源于旧日时代的文字，以神秘亚金烫印，映现出独属于诡秘之主的徽记。"] = "Персонажи эпохи Великого Древнего, отпечатанные методом горячей штамповки из загадочного полузолота и отражающие уникальную эмблему Повелителя Тайн.",
    ["某些神秘，藏在星图里，藏在长夜尽头不肯消散的光里。"] = "Некоторые тайны скрыты в звездных картах, скрыты в свете, который отказывается рассеиваться в конце долгой ночи.",
    ["某位帝王曾在日记里留下一句未完的感慨。经过长久的品鉴，想必这份风味已深入你的身心。"] = "Однажды некий император оставил в своем дневнике незаконченное чувство. После долгого созерцания этот аромат, должно быть, глубоко пропитал ваше тело и разум.",
    ["某位帝王曾在日记里留下一句未完的感慨，现下品鉴确实别有风味。"] = "Некий император однажды оставил в своем дневнике незавершенную эмоцию, и теперь дегустация действительно уникальна.",
    ["柔顺长发划过面庞，烛光中浮动着有如锦缎的光泽。"] = "Мягкие длинные волосы скользили по лицу, переливаясь, как шелк, в свете свечей.",
    ["柔顺额发垂于颊侧，烛光中浮动着有如锦缎的光泽。"] = "Мягкая челка свисает по щекам, плывя в свете свечей с блеском, как шелк.",
    ["梳起整齐的发式，是来到新家的第一课。爱与信仰照拂着孩子们，让灵魂虔诚而纯净。"] = "Аккуратное расчесывание волос – первое занятие по прибытии в новый дом. Любовь и вера сияют на детях, делая их души благочестивыми и чистыми.",
    ["森林呼唤着月亮，三色堇依偎着女贞花；夏夜的幻梦仍未消散，但仙境已经无法关住灿烂的灵魂。"] = "Лес взывает к луне, анютины глазки льнут к цветам бирючины; иллюзии летней ночи еще не развеялись, но волшебной стране уже не удержать сияющую душу.",
    ["歌颂光明，赞美太阳。"] = "Пойте свет, Хвалите Солнце.",
    ["正装和礼帽是绅士的武装，也是这个世界为他烙下的印迹。"] = "Костюм и цилиндр — доспехи джентльмена и отпечаток, который наложил на него этот мир.",
    ["步履不停，在博物馆中追溯往昔也眺望明日。也许，我们也只是历史孔隙中的剪影。"] = "Никогда не переставайте ходить, прослеживая прошлое и глядя в будущее в музее. Возможно, мы всего лишь силуэты в пробелах истории.",
    ["死亡执政官的造物，源于私心的保护。祂允诺的庇佑，将在此烛中长明。"] = "Архонт Смерти был создан из эгоистичной защиты. Его обещанное благословение будет ярко сиять в этой свече.",
    ["每一步都开出轻盈的小花，每一爪都按下软乎乎的承诺，世界因你变得毛绒绒。"] = "Каждый шаг расцветает легкими цветами, каждая лапа оставляет мягкое обещание, мир становится пушистым из-за тебя.",
    ["每根丝上都粘着一段被遗忘的记忆。"] = "На каждой нити застряло забытое воспоминание.",
    ["毒藤缠绕着沉默，暗绿深处藏着致命的优雅。"] = "Ядовитый плющ оплетает тишину, а в темно-зеленых глубинах скрыта смертоносная элегантность.",
    ["毒藤缠绕着沉默，至美存于更加致命之处。"] = "Ядовитый плющ оплетает тишину, а высшая красота существует в самых роковых местах.",
    ["毒蛇缠绕之心，似乎是某种秘仪的仪式用品。"] = "Сердце переплетенной гадюки, похоже, является неким ритуальным предметом для тайной церемонии.",
    ["毛发乌黑的夏尔马。鲁恩王国最常见的役用马匹，它稳重、可靠，负载能力极强，无论出行货运皆为优选。"] = "Черноволосая шайрская лошадь. Самая распространенная тяжеловозная лошадь в Королевстве Лоэн. Он устойчив, надежен и обладает чрезвычайно высокой грузоподъемностью, что делает его отличным выбором как для путешествий, так и для перевозки грузов.",
    ["毛发栗金的夏尔马。鲁恩王国最常见的役用马匹，它稳重、可靠，负载能力极强，无论出行货运皆为优选。"] = "Каштаново-золотая шайрская лошадь. Самая распространенная тяжеловозная лошадь в Королевстве Лоэн. Он устойчив, надежен и обладает очень высокой несущей способностью, что делает его лучшим выбором как для путешествий, так и для грузовых перевозок.",
    ["毛发纯白的夏尔马。鲁恩王国最常见的役用马匹，它稳重、可靠，负载能力极强，无论出行货运皆为优选。"] = "Чисто белая шайрская лошадь. Самая распространенная тяжеловозная лошадь в Королевстве Лоэн. Он устойчив, надежен и обладает чрезвычайно высокой несущей способностью, что делает его лучшим выбором как для путешествий, так и для грузовых перевозок.",
    ["毛绒绒的不对称兔耳，随着行动轻轻晃动。"] = "Пушистые асимметричные кроличьи уши, которые мягко покачиваются при движении.",
    ["毛绒绒的兔耳装饰，带来与众不同的灵动与可爱。"] = "Пушистое украшение в виде кроличьих ушей придаёт неповторимую живость и милоту.",
    ["毛绒绒的对称兔耳，当然也可以随着行动轻轻晃动。"] = "Пушистые симметричные кроличьи уши, которые к тому же могут слегка покачиваться при движении.",
    ["毛绒绒的猫耳装饰，带来令人卸下心防的活泼与俏皮。"] = "Пушистые кошачьи ушки, чья живость и игривость заставляют любого ослабить бдительность.",
    ["水晶灯影下，觥筹交错间，你如铂金般闪耀。"] = "Под светом хрустальной люстры, среди звона бокалов, ты сияешь, как платина.",
    ["永不流动的黄昏停滞于肩甲，哪怕此身沐浴落日，仍有唤醒黎明之志。"] = "Нескончаемый сумрак задерживается на наплечниках; даже если это тело купается в лучах заходящего солнца, остается желание разбудить рассвет.",
    ["永不流动的黄昏凝结于发梢，哪怕此身沐浴落日，仍有唤醒黎明之志。"] = "Никогда не струящийся закат конденсируется на кончиках волос; даже если это тело купается в лучах заходящего солнца, все равно сохраняется стремление разбудить рассвет.",
    ["永恒的美丽还是无尽的孤独，只在你一念之间。"] = "Вечная красота или бесконечное одиночество, все зависит от вашего выбора.",
    ["永眠是安宁的另一种形式，一切的归宿是安宁！"] = "Вечный сон — иная форма покоя, и всё сущее обретает приют в покое!",
    ["波纹涌动，明快的金橙色破开滚滚热浪。水花绽放，夏日登场！"] = "Вздымается рябь, яркий золотисто-оранжевый цвет пробивается сквозь накатывающий зной. Брызги цветут, лето пришло!",
    ["洞悉心灵，旁观万物。"] = "Проницательность в сердце, наблюдайте за всеми вещами.",
    ["流转着微光的蝶形装饰，象征着无常的美丽，与那些注定短暂的停驻。"] = "Мерцающее тусклым светом украшение в виде бабочки, символизирующее красоту непостоянства и мимолётность кратких мгновений.",
    ["浑身散发着“此刻值得信赖”的气场——至少在这一刻如此。"] = "От него прямо-таки веет надежностью — ну, по крайней мере, в эту самую минуту.",
    ["深沉夜色下，切切絮语在沙龙中生长。刚刚，又是谁的雪色绒发拂过了掌心？"] = "В глубокой ночной тьме в салоне зарождается тихий шёпот. Чьи снежно-белые локоны только что коснулись вашей ладони?",
    ["深红如血的战马，大半身躯覆有银色重甲，纹路交织如古老的神秘符号。"] = "Боевой конь цвета крови, большая часть его тела покрыта тяжелыми серебряными доспехами, узоры которых переплетаются, словно древние загадочные символы.",
    ["深红浸透黑暗，疯狂低语在刀锋上盘旋，每一次挥舞，都成为献给邪神的血祭。"] = "Багровый цвет пропитывает тьму, безумный шепот кружится на острие клинка; каждый взмах становится кровавой жертвой злому богу.",
    ["深色皮革包裹的高背座椅，给人厚重而安心的支撑。"] = "Высокое кресло, обтянутое тёмной кожей, даёт ощущение надёжной и основательной опоры.",
    ["深蓝漆面吞尽所有刀光，只在转身刹那折出冷峻的色彩，如宣判，似誓言。"] = "Глубокий синий лак поглощает весь свет клинка, отражая холодный, суровый цвет лишь в момент поворота, как приговор, как клятва.",
    ["清晨的第一缕阳光穿透薄雾，落在初绽的玫瑰与铃兰之上。"] = "Первые лучи утреннего солнечного света пробиваются сквозь тонкий туман и падают на только что распустившиеся розы и ландыши.",
    ["清晨雾霭之中，有精灵留下踪迹。"] = "В утреннем тумане есть следы, оставленные эльфами.",
    ["清甜的风从荒野尽头而来，自道路彼端而去。所有瑰丽的相遇与别离，都盛开于这片生的原野。"] = "Сладкий свежий ветер приходит с края пустошей и уходит на другой конец дороги. Все прекрасные встречи и расставания расцветают на этом поле жизни.",
    ["清醒的头羊，造主的牧者。黑袍下是守护白银城的誓言，直至终焉。"] = "Трезвый вожак стада, пастырь Создателя. Под чёрной мантией — клятва защищать Серебряный город до самого конца.",
    ["潮声漫过长岸，碎光随浪起伏。有人自远方踏水而来，也将新的故事带到眼前。"] = "Шум прилива накатывает на длинный берег, осколки света поднимаются и опускаются с волнами. Кто-то идёт по воде издалека и приносит новые истории.",
    ["火炬燃烧的圣庭中，晨曦逐渐吞噬阴霾——光就是一切的意义。"] = "В святилище, где горят факелы, рассвет постепенно поглощает дымку — свет — смысл всего.",
    ["火焰无需追随纷争，祂降临，纷争便随祂而来。铁与血自此有了名字。"] = "Пламя не обязательно следует за раздором; Он нисходит, и борьба следует за Ним. С тех пор железо и кровь получили свое имя.",
    ["灰白的余烬中，仍有人在追寻存续，将命运的遗存编织成新的脉络。无论始终，时间仍在生长。"] = "Среди серых углей всё ещё есть те, кто ищет продолжение и вплетает остатки судьбы в новые нити. Что бы ни было в начале и в конце, время продолжает расти.",
    ["灵动的发卷在风中跃动，宛如一支悠扬的小夜曲。"] = "Игривые локоны колышутся на ветру, словно тихая серенада.",
    ["灿金光芒交织翡翠清辉，光影浮动，吟咏着一首无声的颂歌。"] = "Яркий золотой свет переплетается с изумрудным сиянием, плывут свет и тень, поющие безмолвный гимн.",
    ["炽热蒸汽覆盖祂所开启的时代。这无尽庞大的阴影之下，机械究竟在消弭众生的哀恸，还是为新的苦难铺设温床？"] = "Раскалённый пар покрывает эпоху, открытую Им. Под этой бесконечно огромной тенью — устраняют ли машины скорбь всего живого, или же готовят почву для новых страданий?",
    ["烈阳的光辉洒落，祈光者在晨祷中接受神圣的加冕。"] = "Падает сияние Пылающего Солнца, и Молитвенник принимает священное венчание во время утренней молитвы.",
    ["烛光摇曳的会客厅，等待着一场盛大的晚宴。"] = "Зал с мерцающим светом свечей в ожидании грандиозного банкета.",
    ["烛泪凝固成月夜的形状，它将给予你安宁。"] = "Слёзы свечей застывают в форме лунной ночи; это даст вам покой.",
    ["烛火静止如凝固的音符，永不熄灭。"] = "Свет свечей неподвижен, как застывшие музыкальные ноты, и никогда не угасает.",
    ["焰燃不熄，同袍之名不灭。"] = "Пламя горит неугасимо, и имена соратников не померкнут.",
    ["狂热的信徒，造主的牧者。将疯狂与血肉铸成神之臂膀，直至终焉。"] = "Одержимый верующий, пастырь Создателя. Кующий безумие и плоть в руку Бога, до самого конца.",
    ["猎物的哀嚎，为这场狩猎画下句点。"] = "Вопли добычи означают конец этой охоты.",
    ["王朝盛时，诸神来贺。整个国境内的欢呼，都被酿成一杯名为昌盛的祝酒。"] = "В расцвете династии боги явились с поздравлениями. Все радостные возгласы по всей стране слились в один тост, названный Процветанием.",
    ["王至，时代为之开辟；王立，权与力为之俯首。"] = "Явится Государь — и пред Ним откроется эпоха; восстанет Государь — и власть с могуществом склонятся пред Ним.",
    ["环上无缺口，正如神选无退路。"] = "В кольце нет разрывов, как и у избранных богом нет пути назад.",
    ["琴声落处，时光停驻。"] = "Там, где падает фортепианная музыка, время останавливается.",
    ["琴弦在风中颤动，奏响无人听懂的歌谣。"] = "Струны трепещут на ветру, наигрывая песнь, которую никому не дано понять.",
    ["甜腻的气息顺着毛茸茸的脑袋散开，令所有严阵以待的非凡者，都忍不住心中柔软。"] = "Сладкий аромат распространился от пушистой головы, заставив всех стоящих рядом Потусторонних невольно почувствовать мягкость в своих сердцах.",
    ["用稚嫩的肩膀撑起莫雷蒂家的天空，于贫寒中不失体面与尊严。"] = "Поддерживая небо семьи Моретти молодыми плечами, сохраняя порядочность и достоинство среди бедности.",
    ["由不出名的小工坊制作的特别月亮灯。特别在于那轮月的色泽——竟然是金黄的。与夜空中悬挂的那轮绯月完全迥异的颜色。"] = "Особенный лунный фонарь, сделанный в безвестной маленькой мастерской. Особенность в том, что цвет луны на нём — золотисто-жёлтый. Совершенно не похож на цвет алой луны, висящей в ночном небе.",
    ["白色石纹的桌面，搭配古典支脚，优雅而内敛的设计风格。"] = "Столешница с белым каменным узором на классических ножках. Элегантный и сдержанный стиль.",
    ["百搭的银边圆框眼镜，不会出错的选择。"] = "Универсальные круглые очки в серебряной оправе: выбор, который никогда не ошибется.",
    ["直面灼热的阳光，不如从手指的缝隙后眺望远方。"] = "Находясь лицом к палящему солнцу, лучше смотреть вдаль из-за щелей пальцев.",
    ["真正自然的柔顺，无需多余的粉饰，仅需剪影即可动人。"] = "По-настоящему естественная гибкость, никаких дополнительных украшений, просто силуэт движется.",
    ["眼角微垂，把全世界都放进余光里。"] = "Глаза слегка опущены, помещая весь мир на периферийное поле зрения.",
    ["短暂的停顿。像是在思考，至于想到了什么，只有沉默知道。"] = "Короткая пауза. Как будто задумавшись; а что же было задумано, знает только молчание.",
    ["石化的翅膀，却有着一颗自由翱翔的心。"] = "Окаменелые крылья, но обладающие свободно парящим сердцем.",
    ["破旧的兔子巴尼是安西娅最最重要的家人，它的纽扣眼睛总好像活物一般凝视着什么。"] = "Измученный кролик Барни — самый важный член семьи Антеи, его глазки-пуговки всегда смотрят на что-то, как будто они живые.",
    ["示意保持安静。原因未明，但在这个世界里，谨慎从不多余。"] = "Жест, призывающий молчать. Причина неизвестна, но в этом мире осторожность никогда не бывает лишней.",
    ["祂的神国高悬于天际，祂的呓语缥缈在云端。唯有祈祷回响于大地之上，记录于圣典之间。"] = "Его божественное царство возвышается в небесах, Его бред неуловимо витает в облаках. Лишь молитвы отзываются эхом на земле, запечатлённые в священных писаниях.",
    ["祂说黑暗将至，于是黑夜以静默将万物收拢于唇齿之间。\n祂说至此安眠，于是夜幕以安宁将众生裹入未醒的国度。\n夜色将一切锋芒收敛，只因你的到来而闪烁，如苏醒于天穹的繁星。"] = "Он сказал, что приближается темнота, поэтому ночь молча сомкнула все вещи между его губами и зубами. \n Он сказал, что пора спать, поэтому ночь окутывает все живое в царство непробужденного умиротворением. \nНочь подавила все острые грани, и сияет только с твоим приходом, как пробуждающиеся на небе звезды.",
    ["祈祷声穿透穹顶化作光环，虔诚在圣殿的石柱间回响不息。"] = "Звуки молитвы пронзают купол, обращаясь в сияющий ореол, и благоговение непрестанно эхом разносится среди каменных колонн собора.",
    ["神光眷顾，星辉闪烁，信仰亦推动群星运转。"] = "Божественный свет благословляет, звёздное сияние мерцает, и вера тоже приводит звёзды в движение.",
    ["神态天真的孩童，靠近他，或许能分得一丝命运的眷顾。"] = "Дети с невинным выражением лица могут получить намек на благосклонность судьбы, если приблизятся к нему.",
    ["神情低落，但情绪尚且收束在可控范围内。"] = "Настроение плохое, но эмоции еще в пределах контролируемого диапазона.",
    ["神情肃穆的雕像。长久立于此处，静默而神圣。"] = "Торжественная статуя. Стою здесь долго, молчаливо и священно.",
    ["神迹荫蔽下的空间，命盘与星光指引未来的轨迹。"] = "Пространство под сенью божественных чудес: колесо судьбы и звёздный свет указывают путь в будущее.",
    ["窥探神秘，求知不止。"] = "Разгадайте тайну и продолжайте искать знания.",
    ["端庄的发式是来到新家的第一课。爱与信仰照拂着孩子们，让灵魂虔诚而纯净。"] = "Достойная прическа – первый урок по приезду в новый дом. Любовь и вера сияют на детях, делая их души благочестивыми и чистыми.",
    ["笑容是精心测量的弧度，藏着无人知晓的秘密。"] = "Улыбка — это тщательно выверенный изгиб, скрывающий тайну, о которой никто не знает.",
    ["简单定型，利落干净，效率至上。"] = "Простой стиль, аккуратный и чистый, эффективность прежде всего.",
    ["简约的黑边眼镜，让佩戴者显得更加博学。"] = "Простые очки в черной оправе, которые придают их владельцу более ученый вид.",
    ["粉色不一定是温柔的代名词。在星光里旋转的爱心，也许带着某种说不清楚的锋利。"] = "Розовый не обязательно является синонимом нежности. Сердце, вращающееся в свете звезд, могло обладать неописуемой остротой.",
    ["繁花和光辉，邀请你加入一场永不落幕的盛宴。"] = "Цветы и сияние приглашают вас присоединиться к празднику, который никогда не заканчивается.",
    ["繁花见证誓约，也为有情人开辟相会的一隅。"] = "Цветы свидетельствуют о Завете, а также создают уголок для встреч влюбленных.",
    ["红月当空，夜幕深沉，耸立的古堡沉默注视着大地。"] = "Красная луна висит в небе, ночь глубока, и возвышающийся древний замок молча взирает на землю.",
    ["红蓝彩条外套配上小丑的礼帽。不变的笑面后，隐藏着无人在意的真心或假意。"] = "Пальто в красно-синюю полоску в сочетании с клоунским цилиндром. За неизменным улыбающимся лицом скрывается искренность или притворство, которое никого не волнует.",
    ["经典的波浪发式，透出来自上个时代的优雅余韵。"] = "Классическая волнистая прическа, раскрывающая элегантное очарование прошлой эпохи.",
    ["绒尾轻摇，于舞会的最高潮成为全场的焦点。在被惊艳的人群中，随心挑选满意的猎物吧。"] = "Взмахнув бархатным хвостом, станьте центром внимания в самый разгар бала. Среди ошеломленной толпы выбирайте добычу по своему желанию.",
    ["美酒芬芳，启迪着那哲学的苗圃与变革的温床；蓝厅中新一轮畅谈开启，而佳话的主角依旧是你。"] = "Аромат прекрасного вина пробуждает питомник философии и колыбель перемен; в Голубом зале начинается новый раунд бесед, и главным героем этой истории остаётесь вы.",
    ["羽翼于辉光舒展，金属于暗影凝结，互为倒影，各自完整。"] = "Крылья расправлены в сиянии, металл застывает в тени, отражения друг друга, каждое целое.",
    ["翻开书本，也步入知识的海洋。"] = "Открой книгу — и шагни в океан знаний.",
    ["翻开它，文字会随着你的思想而跳跃。"] = "Откройте его, и слова пойдут вместе с вашими мыслями.",
    ["脚踏车中最经典的款型，选用独特的蓝白配色重新粉刷后再度推出。当煤气路灯的光芒穿透雨水照耀车身，每个人都将从此处领略到金属的美感。"] = "Самая классическая модель велосипеда, перевыпущенная после перекраски в уникальную сине-белую гамму. Когда свет газового фонаря пробивается сквозь дождь и освещает тело, отсюда каждый оценит красоту металла.",
    ["自此，一切皆有可能。"] = "С этого момента все возможно.",
    ["自灵界纷飞而出的温柔翅翼，虽然无法成为信使，但足以带来一份慰藉。"] = "Нежные крылья, порхающие из Мира Духов, хоть и не могут стать посланниками, но их достаточно, чтобы принести немного утешения.",
    ["至诚至纯的灵魂，将如日光般神圣，赤心颂唱时，太阳也为你首肯。"] = "Самая искренняя и чистая душа будет так же священна, как солнечный свет; когда красное сердце поет, солнце также дает свое согласие на вас.",
    ["芬芳装点了你的镜框，而你却装点了我的梦。"] = "Аромат украшает твою раму, а ты украшаешь мои сны.",
    ["菌丝在叶脉间蔓延，孢子随光点飘散。那片看不见的古老森林，就这样悄然生长于你的周遭。"] = "Мицелий распространяется между жилками листьев, а споры переносятся вместе со светлыми пятнами. Таким образом, вокруг вас незаметно вырос этот невидимый древний лес.",
    ["落日已去，此身即永昼。我立于此地，世界方始得见。"] = "Закат ушел, и это тело — вечный день. Я стою здесь, и только тогда мир начинает видеть.",
    ["虽然花已褪色，却仍旧存在于每一个曾见过它盛开模样之人的梦里。"] = "Хоть цветок и поблёк, он всё ещё живёт в снах каждого, кто видел его в полном цвету.",
    ["血月般绯红的战马，银色战甲覆于胸前，如夜空下的赤色幽灵。"] = "Боевой конь, багровый, как кровавая луна, с серебряной броней, покрывающей грудь, словно красный призрак под ночным небом.",
    ["衣摆如烈焰燃烧，每一步踏着生命的节拍，热情在旋转中迸发。"] = "Подол пылает, как пламя, каждый шаг ложится в ритм жизни, и страсть вспыхивает в кружении.",
    ["裙裾拖曳的声响轻如秘密，只有靠得够近的人，才能听见诱惑在低语。"] = "Звук волочащейся юбки легок, как тайна. Только те, кто находится достаточно близко, могут услышать шепот искушения.",
    ["观众总是置身幕后，静观一切戏剧之欢呼，洞悉一切角色之走向。"] = "Зритель всегда находится за кулисами, спокойно наблюдая радость всех драм, угадывая направление всех ролей.",
    ["视野消失，但世界仍在暗处流动。"] = "Видение исчезает, но мир по-прежнему течет во тьме.",
    ["言出如谕，闻者皆知其分量。"] = "Слово его подобно указу, и всякий слышавший знает его вес.",
    ["誓言无声，却直至生命终焉。"] = "Обет молчаливый, но действует до конца жизни.",
    ["谁说一只猫不能成为大侦探的呢？"] = "Кто сказал, что кот не может стать великим детективом?",
    ["贴上它，思念就开始流浪。"] = "Приклейте его, и тоска начнет бродить.",
    ["赤红光焰在塔顶无声燃烧，光芒笼罩之下，一切都弥漫着铁与血的甜腥，踏入者皆为战争的一部分。"] = "Багровое пламя тихо горит на вершине башни; под покровом света все пронизано сладким рыбным запахом железа и крови, и все входящие становятся частью войны.",
    ["赤诚如新月初绽，无声的誓言比鲜血更炽热。"] = "Искренние, как цветущая новая луна, молчаливые клятвы горячее крови.",
    ["蹲在头顶的笑意温暖你的发间。"] = "Улыбка, сияющая на твоей голове, согревает твои волосы.",
    ["身着长袍的女性，周身散发着柔和的微光。她静静伫立，似乎在无声地庇佑着此处。"] = "Женщина в халате, излучающем мягкое сияние. Она стоит спокойно, словно молча защищая это место.",
    ["身着雨披行于街角，让绵密的水珠从身侧滑落，你就是夜里一盏温暖的灯。"] = "Идя по углу улицы в плаще, позволяя плотным каплям скатываться с бока, ты - теплый светильник в ночи.",
    ["身着雾霭和尘埃，在万都之都的角落寻找属于自己的晴天。"] = "Окутанный смогом и пылью, в закоулках Столицы столиц он ищет свой собственный ясный день.",
    ["轻柔的细语与激情的轰拳，都可以完成一场难以抵抗的长眠。"] = "Тихий шепот и страстные удары могут завершить непреодолимый долгий сон.",
    ["追寻自由，探索未知。"] = "Стремитесь к свободе, исследуйте неизведанное.",
    ["透过白枫宫恢弘的王座，凝望那位传奇的一生。那足以背离世界的执念，只系于一声迟到的呼唤。"] = "Сквозь величественный трон Дворца Белого клёна вглядитесь в жизнь той легенды. Одержимость, способная отвернуть от мира, была привязана лишь к одному опоздавшему зову.",
    ["那位造物主曾说：要有光。于是，祂座下的神性以光环代言。"] = "Тот Создатель некогда сказал: Да будет свет. И тогда божественность у Его престола стала выражаться через ореол.",
    ["邮票是小小的门扉，可以从中窥见那位时代主角一生中的掠影。"] = "Штамп — это маленькая Дверь, из которой можно увидеть тени жизни главного героя той эпохи.",
    ["金秋之境，遗迹丰景，凋萎变作新生，枯叶破茧成蝶。"] = "Златоосенний край, обитель древних руин; увядание сменяется возрождением, а сухие листья бабочками вырываются из кокона.",
    ["鎏金光柱自塔顶垂落，在此一切都被律令所定义，寂静中蕴含着裁决万物的威严。"] = "Золотой столб света падает с вершины башни; здесь все определено указом, и молчание содержит величие Суда над всеми вещами.",
    ["铁轨延伸至远方，工具叮当作响，一场蒸汽与引擎声交织的铁道之旅自此展开。"] = "Пути уходят вдаль, гремят инструменты, и здесь начинается железнодорожное путешествие, сотканное из звуков пара и моторов.",
    ["银纹织就的誓言在肩头沉淀，铁与布在风中低语，像某种无声的律令。"] = "Клятва, вытканная серебряными узорами, ложится на плечи; железо и ткань шепчут на ветру, словно безмолвный закон.",
    ["闪烁微光的水晶球，仿佛能映出人最真实的内心。"] = "Мерцающий хрустальный шар, будто способный отразить самое истинное сердце человека.",
    ["阳光在晨起时就打了照面，晴朗的一天从现在开始。"] = "Солнечный свет приветствовал нас на рассвете; солнечный день начинается сейчас.",
    ["雕刻精美的花瓶，其中摆放着娇嫩而艳丽的粉色鲜花，静静散发着香气。"] = "Искусно вырезанная ваза с нежными яркими розовыми цветами тихо источает аромат.",
    ["雕纹庄重，内心“草率”，一本正经地搞绿化。"] = "Торжественная резьба, легкомысленная душа — с невозмутимым видом занимается озеленением.",
    ["非凡之路的起点，序列尚未显名，但力量已在无声中苏醒，等待命运的召唤。"] = "Начальная точка пути Потустороннего; Последовательность еще не раскрыта, но сила уже в тишине пробудилась, ожидая зова судьбы.",
    ["食指与拇指轻触成心形，像一只蝴蝶停在空中，等你来认领。"] = "Указательный и большой пальцы соприкасаются, образуя форму сердца, словно бабочка, парящая в воздухе и ожидающая, пока вы заберете ее.",
    ["骰子是骰子，运气是运气。至于为什么每次都赢……纯属巧合。"] = "Кости — это кости, удача — это удача. А почему я выигрываю каждый раз... чистое совпадение.",
    ["鲁恩最大脚踏车公司推出的新款车型，配色独特，每一位拥抱潮流的时尚人士都会为它而侧目。此为胡桃配色。"] = "Новая модель, выпущенная крупнейшей велосипедной компанией Лоэн, с уникальной цветовой гаммой, которая привлечет внимание каждой модницы, следящей за тенденциями. Это цвет ореха.",
    ["鲁恩最大脚踏车公司推出的新款车型，配色独特，每一位拥抱潮流的时尚人士都会为它而侧目。此为苔原配色。"] = "Новая модель, выпущенная крупнейшей велосипедной компанией Лоэн, с уникальной цветовой гаммой, которая привлечет внимание каждого модника. Это расцветка Tundra.",
    ["鲁恩最大脚踏车公司推出的新款车型，配色独特，每一位拥抱潮流的时尚人士都会为它而侧目。此为铜青配色。"] = "Новая модель, выпущенная крупнейшей велосипедной компанией Loen, имеет уникальную цветовую гамму, которая привлечет внимание каждой модницы, которая следит за этой тенденцией. Это бронзовый цвет.",
    ["鲁恩最大脚踏车公司推出的新款车型，配色独特，每一位拥抱潮流的时尚人士都会为它而侧目。此为麦金配色。"] = "Новая модель, выпущенная крупнейшей велосипедной компанией Лоэн, с уникальной цветовой гаммой, которая привлечет внимание каждой модницы, поддерживающей эту тенденцию. Это цветовая гамма Маккина.",
    ["黄沙掩埋往昔，祂的凝视穿透时光，烈日的梦从未消散。"] = "Желтый песок хоронит прошлое; Его Взгляд пронзает время, и мечта о палящем солнце так и не рассеялась.",
    ["黄沙掩埋往昔，祂的凝视穿透时光，烈日的梦愈加灼热。"] = "Желтый песок хоронит прошлое, Его взгляд пронзает время, и мечта о палящем солнце становится еще жгуче.",
    ["黄金枝叶编织王冠，丛影深处自有不朽，藤蔓缠绕金箔，森林也将低眉。"] = "Корона из золотых ветвей и листьев сплетена, и бессмертие существует в глубине теней. Лозы обернуты золотой фольгой, и лес тоже склонит брови.",
    ["黑夜与猩红是缠绕在血族恒长生命上的荆棘，危险、 美丽，并使人刺痛不已。"] = "Ночь и алый — шипы, оплетающие вечную жизнь Рода Крови; опасен, прекрасен и жалит сердце.",
    ["黑夜尚未退场，天光已悄然探入，此刻你可以亲眼见证黎明的到来。"] = "Ночь ещё не отступила, но свет дня уже тихо проник сюда. Сейчас ты можешь собственными глазами увидеть приход рассвета.",
    ["黑白键沉默着，等一双手来唤醒沉睡的音符。"] = "Черно-белые клавиши молчат, ожидая, пока пара рук разбудит спящие ноты.",
    ["黑色是黑夜赐予的隐秘，红色是戒律的森严。女神的使者们，为守护而行。"] = "Черный — тайна, дарованная Ночью; красный – строгость заповедей. Посланники Богини идут защищать.",
    ["黑色的长发像冷夜的雨。"] = "Черные длинные волосы, словно дождь холодной ночью.",
}
